@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;0,700;0,800;1,600;1,700&display=swap');
:root {
--bg:#101210;--panel:#171a17;--panel2:#1d211d;--line:#292e29;--muted:#858b81;--text:#f1f0e9;--green:#c8f169;--green-d:#819b40;--red:#ff806d;--board-light:#e9dfc9;--board-dark:#788269;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif;--serif:'Playfair Display',serif}

* {
box-sizing:border-box}
body {
margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 60% -30%,#272c22 0,transparent 55%)}
button,select {
font:inherit;color:inherit}
button {
cursor:pointer}
.app-shell {
max-width:1600px;margin:auto;padding:0 40px}
.topbar {
height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}
.brand {
display:flex;align-items:center;gap:12px;color:var(--text);text-decoration:none}
.brand-mark {
width:37px;height:37px;border:1px solid #444b3e;background:#242a20;color:var(--green);display:grid;place-items:center;font-size:25px;border-radius:10px}
.brand-copy {
display:grid;gap:2px}
.brand-copy strong {
font-size:12px;letter-spacing:1.55px}
.brand-copy small,.eyebrow,.top-center,.session-label,.rail-foot,.settings-title,.select-label,.level-row>span,.voice-row label,.voice-style>span,.footer {
font-family:var(--mono);letter-spacing:1px;font-size:9px;color:var(--muted)}
.brand-copy small {
font-size:8px;letter-spacing:1.25px}
.top-center {
font-size:10px;display:flex;align-items:center;gap:10px}
.live-dot,.engine-pulse,.online-dot {
display:inline-block;width:7px;height:7px;background:var(--green);border-radius:50%;box-shadow:0 0 10px #c8f16970}
.top-actions {
display:flex;align-items:center;gap:18px}
.icon-btn,.profile-chip {
background:none;border:0;color:#d9ded3}
.icon-btn {
font-size:15px}
.profile-chip {
display:flex;align-items:center;gap:9px;font-size:9px;letter-spacing:1px}
.avatar {
width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:#8b9b74;color:#162011;font-weight:800;font-size:12px}
.layout {
display:grid;grid-template-columns:208px minmax(0,1fr);gap:44px;padding:35px 0 22px}
.left-rail {
position:relative;display:flex;flex-direction:column;min-height:750px}
.eyebrow {
font-size:9px;color:#92988b}
.mode-nav {
display:grid;gap:5px;margin-top:17px}
.mode-item {
display:flex;align-items:center;gap:12px;height:41px;border:0;background:transparent;color:#a6aaa2;text-align:left;padding:0 12px;border-radius:5px;font-size:12px;transition:.18s}
.mode-item:hover {
background:#1b201a;color:#fff}
.mode-item.active {
color:var(--green);background:#22291d;box-shadow:inset 2px 0 var(--green)}
.mode-icon {
font-size:17px;width:18px;text-align:center;color:#8e9788}
.mode-item.active .mode-icon {
color:var(--green)}
.nav-arrow {
margin-left:auto;font-size:14px}
.hot-tag,.tiny-18 {
font:9px var(--mono);color:#e6a18c;background:#3a2521;border-radius:3px;padding:3px 4px;margin-left:auto}
.rail-divider {
border-top:1px solid var(--line);margin:23px 0 21px}
.session-card {
padding:15px 14px;background:#171a16;border:1px solid #252b24;border-radius:6px}
.session-label {
font-size:8px;margin-bottom:16px}
.stat-line {
display:flex;justify-content:space-between;padding:6px 0;color:#9da398;font-size:11px}
.stat-line strong {
font-family:var(--mono);font-size:11px;color:#e8e9df}
.stat-foot {
padding-top:12px;margin-top:7px;border-top:1px solid var(--line);font-size:10px;line-height:1.7;color:#747b70}
.rail-foot {
margin-top:auto;white-space:nowrap;font-size:8px;display:flex;align-items:center;gap:7px}
.engine-pulse {
width:6px;height:6px}
.engine-state {
color:var(--green);margin-left:auto}
.game-heading {
display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:23px}
.game-heading .eyebrow {
font-size:8px}
.heading-sep {
color:#4d534b;margin:0 5px}
.game-heading h1 {
font:600 clamp(25px,2.7vw,35px)/1.2 var(--serif);margin:9px 0 0;letter-spacing:-.7px}
.game-heading h1 em {
color:var(--green);font-weight:600}
.more-btn {
display:flex;align-items:center;gap:8px;border:1px solid #333a31;border-radius:4px;padding:10px 12px;background:#1a1e19;color:#cdd2c5;font:9px var(--mono);letter-spacing:.7px}
.more-btn:hover,.control-btn:hover {
border-color:var(--green);color:var(--green)}
.game-grid {
display:grid;grid-template-columns:minmax(420px,1fr) minmax(270px,310px);gap:30px;align-items:start}
.board-column {
min-width:0}
.player-strip {
height:53px;display:flex;align-items:center;gap:11px}
.opponent-strip {
margin-bottom:9px}
.user-strip {
margin-top:9px}
.player-avatar {
height:34px;width:34px;border-radius:5px;display:grid;place-items:center;font-size:23px}
.bot-avatar {
background:#2c3328;color:var(--green)}
.user-avatar {
background:#333c31;color:#f0f0e9;font-size:13px;font-weight:800}
.player-info {
display:grid;gap:4px}
.player-info strong {
font-size:10px;letter-spacing:.8px}
.player-info small {
color:#858c80;font-size:9px}
.accent {
color:var(--green)}
.you-tag {
font-size:8px;color:#91988b}
.rating {
margin-left:auto;color:#b1ba9f;font-size:12px}
.rating b {
font:10px var(--mono);color:#aab19f}
.clock {
min-width:58px;text-align:center;border:1px solid #32382f;background:#1c211b;border-radius:4px;padding:7px 9px;font:11px var(--mono);color:#e7ebdf;margin-left:12px}
.board-frame {
position:relative;padding-left:22px}
.chessboard {
width:100%;aspect-ratio:1;display:grid;grid-template-columns:repeat(8,1fr);grid-template-rows:repeat(8,1fr);border:1px solid #474d3f;box-shadow:0 16px 50px #0008;overflow:hidden;touch-action:manipulation;user-select:none}
.square {
position:relative;display:grid;place-items:center;cursor:pointer;aspect-ratio:1}
.square.light {
background:var(--board-light)}
.square.dark {
background:var(--board-dark)}
.square.selected {
box-shadow:inset 0 0 0 4px #c8f169b8}
.square.last-move {
background-image:linear-gradient(#c8f16954,#c8f16954)}
.square.check-square {
background-image:radial-gradient(circle,#d84e3eaa 12%,#d84e3e55 70%)}
.piece {
font-family:'DejaVu Sans',serif;line-height:1;position:relative;z-index:2;font-size:clamp(28px,5.2vw,61px);transition:transform .12s;filter:drop-shadow(0 2px 1px #0005)}
.square:hover .piece {
transform:translateY(-2px)}
.piece.white {
color:#fffdf1;text-shadow:0 1px 2px #172015,1px 2px 1px #172015,-1px -1px 0 #72776b}
.piece.black {
color:#222822;text-shadow:0 1px 1px #fff5}
.legal-dot {
position:absolute;width:24%;height:24%;border-radius:50%;background:#21301c55;z-index:1}
.square:has(.piece) .legal-dot {
width:88%;height:88%;background:transparent;border:4px solid #d5ef827a}
.coord {
position:absolute;z-index:3;font:9px var(--mono);pointer-events:none}
.coord.file {
right:4px;bottom:2px}
.coord.rank {
left:4px;top:3px}
.light .coord {
color:#687157}
.dark .coord {
color:#e7dfca}
.eval-bar {
position:absolute;top:0;bottom:0;left:0;width:14px;background:#ece9df;border-radius:2px;overflow:hidden}
.eval-fill {
position:absolute;left:0;right:0;bottom:0;height:50%;background:#43483e;transition:height .4s}
.eval-text {
position:absolute;top:50%;left:0;width:100%;text-align:center;transform:translateY(-50%) rotate(-90deg);font:7px var(--mono);color:#131510;mix-blend-mode:difference;z-index:2}
.board-controls {
display:flex;gap:8px;margin-top:14px}
.control-btn {
height:34px;flex:1;background:#1a1d1a;border:1px solid #2e342d;border-radius:4px;color:#9ca397;font:8px var(--mono);letter-spacing:.45px}
.control-btn:first-child {
flex:1.2}
.control-btn span {
margin-left:4px}
.right-panel {
display:grid;gap:13px}
.panel-tabs {
display:flex;height:35px;border-bottom:1px solid var(--line);gap:21px}
.panel-tab {
background:none;border:0;padding:0 0 10px;color:#7e857b;font:9px var(--mono);letter-spacing:.6px;position:relative}
.panel-tab.selected {
color:var(--green)}
.panel-tab.selected:after {
content:'';position:absolute;bottom:-1px;left:0;right:0;height:2px;background:var(--green)}
.tab-count {
font:8px var(--mono);color:#192014;background:var(--green);padding:2px 4px;border-radius:3px}
.coach-card,.settings-card {
background:#171a17;border:1px solid #282e27;border-radius:6px}
.coach-card {
min-height:225px}
.coach-head {
padding:14px 14px 12px;border-bottom:1px solid #272c26;display:flex;align-items:center;gap:10px}
.coach-avatar {
width:32px;height:32px;border-radius:5px;display:grid;place-items:center;background:#293121;color:var(--green);font-size:22px}
.coach-head strong {
display:block;font-size:10px}
.coach-head small {
display:block;margin-top:4px;color:#777f74;font:7px var(--mono);letter-spacing:.5px}
.online-dot {
margin-left:auto;width:6px;height:6px}
.comment-view {
padding:13px 15px 12px}
.comment-meta {
display:flex;justify-content:space-between;align-items:center}
.comment-tag {
font:8px var(--mono);color:#a3b675;background:#28301f;padding:4px 6px;border-radius:2px}
.comment-meta time {
font:8px var(--mono);color:#697067}
.comment-text {
font:500 13px/1.65 var(--serif);color:#d9dbd1;margin:13px 0 18px;min-height:66px}
.comment-actions {
display:flex;align-items:center;justify-content:space-between}
.replay-btn {
border:0;background:none;color:var(--green);font:9px var(--mono);padding:3px}
.voice-caption {
font:7px var(--mono);letter-spacing:.3px;color:#697166}
.moves-view {
height:173px;overflow:auto;padding:10px 14px}
.move-list {
display:grid;grid-template-columns:27px 1fr 1fr;gap:2px;font:11px var(--mono);color:#c6cabc}
.move-number {
color:#747b70}
.move-entry {
padding:5px 6px;border-radius:3px}
.move-entry.latest {
background:#293121;color:var(--green)}
.empty-moves {
grid-column:span 3;text-align:center;color:#747b70;font-size:11px;line-height:1.8;padding:26px 0}
.hidden {
display:none!important}
.settings-card {
padding:13px 14px}
.settings-title {
display:flex;justify-content:space-between;align-items:center;color:#a9b19f;font-size:8px;margin-bottom:14px}
.settings-cog {
font-size:14px;color:#6b7566}
.select-label {
display:block;font-size:8px;margin-bottom:7px}
.settings-card select {
width:100%;height:34px;background:#20241f;border:1px solid #343a32;border-radius:3px;padding:0 9px;color:#daddd2;font-size:10px;outline:none}
.profanity-toggle {
display:flex;justify-content:space-between;align-items:center;padding:13px 0 11px;margin-top:8px;border-bottom:1px solid #292e28}
.profanity-toggle strong {
font-size:9px;letter-spacing:.5px}
.profanity-toggle small {
display:block;font-size:8px;color:#798074;margin-top:4px}
.tiny-18 {
font-size:7px;padding:2px 3px}
.switch {
width:34px;height:19px;border:1px solid #484e44;border-radius:20px;background:#292e28;padding:2px;transition:.2s}
.switch span {
display:block;width:13px;height:13px;border-radius:50%;background:#888f82;transition:.2s}
.switch.on {
background:#748a3a;border-color:#a6ca55}
.switch.on span {
transform:translateX(15px);background:#f0ffd0}
.level-row {
display:flex;justify-content:space-between;align-items:center;padding:10px 0 8px}
.level-row>span,.voice-row label,.voice-style>span {
font-size:7px}
.levels {
display:flex;gap:4px}
.levels button {
width:24px;height:21px;background:#222620;border:1px solid #343a32;border-radius:3px;color:#8e958a;font:9px var(--mono)}
.levels button.selected {
border-color:#b6db67;color:var(--green);background:#29321f}
.voice-row {
display:flex;align-items:center;gap:9px;padding:4px 0 11px}
.voice-row label {
white-space:nowrap}
.voice-row input {
width:100%;height:3px;accent-color:var(--green)}
.voice-row>span {
font:8px var(--mono);color:#adb3a7}
.voice-style {
display:flex;align-items:center;gap:9px}
.voice-style select {
height:29px;font-size:9px}
.resign-btn {
width:100%;height:35px;text-align:left;padding:0 12px;background:transparent;border:1px solid #35362f;border-radius:4px;color:#8d9187;font:8px var(--mono);letter-spacing:.55px}
.resign-btn span {
float:right;color:#c1897e}
.resign-btn:hover {
border-color:#a8786e;color:#d69c8d}
.footer {
border-top:1px solid var(--line);height:44px;display:flex;align-items:center;justify-content:space-between;font-size:8px;letter-spacing:.65px}
.footer span:last-child {
color:#687066}
.modal {
position:fixed;inset:0;background:#080a08cc;backdrop-filter:blur(8px);display:grid;place-items:center;z-index:10;padding:20px}
.modal-card {
width:min(440px,100%);background:#1b2019;border:1px solid #3b4533;border-radius:9px;padding:27px;text-align:center;box-shadow:0 20px 70px #000b}
.modal-card h2 {
font:600 25px var(--serif);margin:12px 0 24px}
.promotion-options {
display:flex;justify-content:center;gap:12px}
.promotion-options button {
display:grid;gap:5px;place-items:center;width:68px;height:75px;border:1px solid #3c4436;background:#252b22;border-radius:5px;font-size:38px;color:#f4f0e6}
.promotion-options button:hover {
border-color:var(--green);color:var(--green)}
.promotion-options small {
font:8px var(--mono);color:#91988a}
.toast {
position:fixed;bottom:28px;left:50%;transform:translate(-50%,20px);padding:11px 16px;background:#30382a;border:1px solid #52643a;border-radius:4px;color:#e4efcd;font-size:11px;opacity:0;pointer-events:none;transition:.2s;z-index:20;white-space:nowrap}
.toast.show {
opacity:1;transform:translate(-50%,0)}

@media(max-width:1100px) {
.app-shell {
