.layout {
padding-top:18px;gap:6px}
.mode-nav {
margin:0 -14px 16px;padding:0 14px 5px}
.mode-item {
font-size:9px;padding:0 9px;height:32px}
.mode-icon {
display:none}
.game-heading {
align-items:center;margin-bottom:12px}
.game-heading h1 {
font-size:25px}
.more-btn {
padding:8px;font-size:12px}
.more-btn span {
display:none}
.game-grid {
display:flex;flex-direction:column;gap:14px}
.board-column,.right-panel {
width:100%}
.board-frame {
padding-left:17px}
.piece {
font-size:min(10.3vw,49px)}
.player-strip {
height:43px}
.player-avatar {
width:30px;height:30px}
.player-info strong {
font-size:9px}
.player-info small {
font-size:8px}
.clock {
margin-left:6px;min-width:48px;padding:6px;font-size:10px}
.board-controls {
margin-top:9px;gap:5px}
.control-btn {
height:32px;font-size:7px;padding:0 2px}
.control-btn span {
font-size:7px}
.right-panel {
gap:9px}
.panel-tabs {
height:32px}
.coach-card {
min-height:0}
.comment-text {
min-height:auto;margin:11px 0 14px;font-size:14px}
.moves-view {
height:140px}
.settings-card {
padding:12px}
.footer {
height:auto;min-height:38px;font-size:6px;gap:12px}
.footer span:first-child {
max-width:48%}
.footer span:last-child {
text-align:right}
.game-heading .eyebrow {
font-size:7px}
.rating {
display:none}
}

@media(max-width:380px) {
.mode-item {
font-size:8px;padding:0 7px}
.board-controls .control-btn span {
font-size:6px}
.game-heading h1 {
font-size:22px}
.brand-copy strong {
font-size:10px}
.brand-copy small {
font-size:7px}
}

